import sys
from collections import deque

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n1 = int(next(iterator))
        n2 = int(next(iterator))
        m = int(next(iterator))
    except StopIteration:
        return

    edges = []
    for i in range(m):
        u = int(next(iterator))
        v = int(next(iterator))
        edges.append((u, v, i + 1))

    adj_u = [[] for _ in range(n1 + 1)]
    adj_v = [[] for _ in range(n2 + 1)]

    for idx, (u, v, eid) in enumerate(edges):
        adj_u[u].append((v, idx))
        adj_v[v].append((u, idx))

    deg_u = [len(adj_u[i]) for i in range(n1 + 1)]
    deg_v = [len(adj_v[i]) for i in range(n2 + 1)]

    min_degree = float('inf')
    if n1 > 0:
        for d in deg_u[1:]:
            if d < min_degree:
                min_degree = d
    if n2 > 0:
        for d in deg_v[1:]:
            if d < min_degree:
                min_dimension = d

    if min_degree == float('inf'):
        min_degree = 0

    if min_degree == 0:
        print("0")
        return

    current_edges = list(range(m))

    results = []

    for k in range(1, min_degree + 1):
        active = [True] * m
        count_active = m

        deg_u_curr = [len(adj_u[i]) for i in range(n1 +  1)]
        deg_v_curr = [len(adj_v[i]) for i in range(n2 +  1)]

        q = deque()

        for i in range(1, n1 + 1):
            if deg_u_curr[i] < k:
                q.append(('u', i))
        for j in range(1, n2 + 1):
            if deg_v_curr[j] < k:
                q.append(('v', j))

        while q:
            side, idx = q.popleft()

            if side == 'u':
                neighbors = adj_u[idx]
            else:
                neighbors = adj_v[idx]

            for other_idx, edge_idx in neighbors:
                if active[edge_idx]:
                    active[edge_idx] = False
                    count_active -= 1

                    if side == 'u':
                        deg_v_curr[other_idx] -= 1
                        if deg_v_curr[other_idx] < k:
                            q.append(('v', other_idx))
                    else:
                        deg_u_curr[other_idx] -= 1
                        if deg_u_curr[other_idx] < k:
                            q.append(('u', other_idx))

        selected_indices = [edges[i][2] for i in range(m) if active[i]]
        results.append((len(selected_indices), selected_indices))

    output_lines = []
    for cnt, indices in results:
        if cnt == 0:
            output_lines.append("0")
        else:
            output_lines.append(f"{cnt} " + " ".join(map(str, indices)))

    print("\n".join(output_lines))

if __name__ == "__main__":
    solve()
